#[test]
fn test_health_scores() {
    crate::testport::assert_eq(th_score(1000, 0, 0, 0), 1000, "a perfect font");
    crate::testport::assert_eq(th_score(1000, 0, 500, 500), 1000, "the limits are free");
    crate::testport::assert_that(th_score(1000, 0, 100, 0) >= th_trusted(), "a normal font is trusted");
    crate::testport::assert_that(th_score(0, 1000, 0, 0) < 300, "an unmapped font is far under 300");
    crate::testport::assert_that(th_score(500, 0, 0, 0) < th_trusted(), "half unmapped is not trusted");
    crate::testport::assert_that(th_score(1000, 0, 1000, 0) < th_auto_health(), "every glyph on its neighbour is not healthy");
    crate::testport::assert_that(th_score(1000, 0, 0, 3000) < th_auto_health(), "words torn apart are not healthy");
    crate::testport::assert_that(th_score(1000, 500, 0, 0) < th_trusted(), "half garbage is not trusted");
    crate::testport::assert_that(th_score(800, 0, 0, 0) > th_score(600, 0, 0, 0), "more mapped, better");
}
pub(crate) fn tt_health(file: &[u8], which: i32) -> i32 {
    // Run a document to its health rows; answer, for which 0 the rows, 1 how many are at least `tl-trusted`, 2 the lowest score,
    // 3 the highest score of the rows that are not at least `tl-trusted`.
    let ar: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let dc: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let a: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let b: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cx: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ox: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let f0: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let f1: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let f2: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let f3: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let gl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mk: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let fnt: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pg: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let wd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ln: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pa: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let im: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pts: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let gx: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let epages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let feats: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let fw: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let fl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let fa: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let hl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let sc: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let src: &crate::port::Src = &crate::port::src_of_blob(file);
    let o: i32 = pd_open(src, ar, dc, a, b, st);
    let mut i: i32 = 0;
    let mut good: i32 = 0;
    let mut low: i32 = 100000;
    let mut high: i32 = 0;
    if o != 0 {
        return -1;
    }
    pc_document(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln, pa, im, pts, gx);
    th_run(pg, gl, et, mk, fnt, wd, ln, im, epages, feats, fw, fl, fa, hl, sc);
    while i < hl_count(hl) {
        if hl_get(hl, i, hlf_score()) >= th_trusted() {
            good += 1;
        } else if hl_get(hl, i, hlf_score()) > high {
            high = hl_get(hl, i, hlf_score());
        }
        if hl_get(hl, i, hlf_score()) < low {
            low = hl_get(hl, i, hlf_score());
        }
        i += 1;
    }
    if which == 0 {
        return hl_count(hl);
    }
    if which == 1 {
        return good;
    }
    if which == 2 {
        return low;
    }
    return high;
}
#[test]
fn test_an_unmapped_font_is_caught_and_a_shifted_one_is_not() {
    // tl-broken-unmapped: one font whose glyphs have no Unicode (score far under 300); every other font of both pages is trusted
    crate::testport::assert_eq(tt_health(&crate::testport::test_file("corpus/synth/pdf/tl-broken-unmapped.pdf")[..], 0), 7, "unmapped: rows");
    crate::testport::assert_eq(tt_health(&crate::testport::test_file("corpus/synth/pdf/tl-broken-unmapped.pdf")[..], 1), 5, "unmapped: trusted rows");
    crate::testport::assert_that(tt_health(&crate::testport::test_file("corpus/synth/pdf/tl-broken-unmapped.pdf")[..], 2) < 300, "unmapped: the broken font is under 300");
    // tl-broken-shift: a plausible mapping that is wrong; the text layer cannot tell, OCR agreement can (P7.2)
    crate::testport::assert_eq(tt_health(&crate::testport::test_file("corpus/synth/pdf/tl-broken-shift.pdf")[..], 0), tt_health(&crate::testport::test_file("corpus/synth/pdf/tl-broken-shift.pdf")[..], 1), "shifted: every font passes");
}
#[test]
fn test_healthy_documents_are_trusted() {
    crate::testport::assert_eq(tt_health(&crate::testport::test_file("corpus/synth/pdf/align-rtl.pdf")[..], 0), tt_health(&crate::testport::test_file("corpus/synth/pdf/align-rtl.pdf")[..], 1), "rtl");
    crate::testport::assert_eq(tt_health(&crate::testport::test_file("corpus/synth/pdf/bank-statement.pdf")[..], 0), tt_health(&crate::testport::test_file("corpus/synth/pdf/bank-statement.pdf")[..], 1), "bank statement");
    crate::testport::assert_eq(tt_health(&crate::testport::test_file("vis/visible.pdf")[..], 0), tt_health(&crate::testport::test_file("vis/visible.pdf")[..], 1), "visible");
}
